//! Scaffold a new binary (wiring) app: `apps/<name>/system.toml`.
//!
//! The app's `Cargo.toml` and `src/main.rs` are NOT written here — they are
//! generated by `cargo blox generate` from the system.toml manifest
//! (invariant #18: system.toml is the single source of truth for wiring).

use anyhow::Result;
use std::fs;
use std::path::Path;

use crate::utils::{to_camel_case, update_workspace_cargo_toml, WorkspaceAddition};

pub fn new_binary(name: &str, runtime: &str) -> Result<()> {
    let name_snake = name.to_lowercase().replace("-", "_");
    let name_camel = to_camel_case(name);

    let apps_dir = Path::new("apps");
    let crate_dir = apps_dir.join(&name_snake);
    fs::create_dir_all(&crate_dir)?;

    let system_toml = format!(
        r#"# Copyright 2025 Bloxide, all rights reserved
# Wiring manifest for the {name_camel} system — the single source of truth
# for the generated main.rs and Cargo.toml (regenerate: cargo blox generate).
[system]
runtime = "{runtime}"
name = "{name_snake}"

[[actors]]
name = "{name_snake}"
blox = "{name_snake}-blox"

  # Bootstrap: one Tick so the demo actor runs and exits cleanly.
  [[actors.bootstrap]]
  message = "{name_camel}Msg::Tick"

[[supervision]]
supervisor = "bloxide-supervisor"
strategy = "one_for_one"
children = ["{name_snake}"]

  [supervision.policies]
  {name_snake} = {{ stop = true }}
"#
    );
    let system_path = crate_dir.join("system.toml");
    fs::write(&system_path, system_toml)?;

    let member_path = format!("apps/{}", name_snake);
    update_workspace_cargo_toml(&[WorkspaceAddition::Member(member_path)])?;

    println!("Created: {}", system_path.display());
    Ok(())
}
